WITH gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS session_start_flag FROM transactions), sessionized AS (SELECT id, account_id, amount, txn_time, merchant, SUM(session_start_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT id, account_id, merchant, session_id FROM sessionized ORDER BY merchant DESC NULLS FIRST, id DESC;
